<?php
$title='Transaksi saya';$tab=get('tab','active');if(!in_array($tab,['active','completed'],true))$tab='active';
$active=$service->transactions((int)$user['id'],'active');$completed=$service->transactions((int)$user['id'],'completed');$transactions=$tab==='active'?$active:$completed;
$awaiting=count(array_filter($active,fn($t)=>$t['return_status']==='awaiting'));
?>
<div class="page-heading"><div><p class="greeting">Halo, <?=h(explode(' ',$user['name'])[0])?>.</p><h1>Transaksi saya</h1><p>Pantau barang yang kamu pinjam dan bagikan.</p></div><span class="date-label"><?=icon('clock')?><?=h(dateLabel(date('Y-m-d')))?></span></div>
<section class="sharing-banner"><div><span class="pill">Lingkaran yang saling menjaga</span><h2>Barang kembali.<br>Manfaat berlanjut.</h2><p>Kembalikan tepat waktu, pastikan kondisinya terjaga.<br>Hal kecil yang berarti untuk pemilik berikutnya.</p></div><div class="banner-art" aria-hidden="true"><span class="banner-circle"></span><img src="/assets/book.svg" alt=""><span class="banner-label"><?=icon('check')?>Dipakai. Dijaga. Dikembalikan.</span></div></section>
<div class="activity-strip"><span><?=icon('swap')?><strong><?=count($active)?></strong> transaksi aktif</span><span><?=icon('clock')?><strong><?=$awaiting?></strong> menunggu konfirmasi</span><span><?=icon('check')?><strong><?=count($completed)?></strong> selesai</span></div>
<div class="list-toolbar"><div class="tabs"><a href="<?=h(url('transactions'))?>" class="<?=$tab==='active'?'active':''?>" <?=$tab==='active'?'aria-current="page"':''?>>Aktif <span><?=count($active)?></span></a><a href="<?=h(url('transactions',['tab'=>'completed']))?>" class="<?=$tab==='completed'?'active':''?>" <?=$tab==='completed'?'aria-current="page"':''?>>Selesai <span><?=count($completed)?></span></a></div><span class="result-count"><?=count($transactions)?> transaksi</span></div>
<?php if(!$transactions):?><section class="empty-state"><div class="empty-icon"><?=icon('box')?></div><h2>Belum ada transaksi <?=$tab==='active'?'aktif':'selesai'?>.</h2><p>Transaksi akan muncul di sini sesuai tahap pengembaliannya.</p></section><?php else:?><div class="transaction-grid"><?php foreach($transactions as $t):$borrower=$t['borrower_id']===$user['id'];?><article class="transaction-card"><div class="transaction-card-art"><img src="<?=h(imagePath($t))?>" alt="<?=h($t['item_name'])?>"><?=badge(state($t))?></div><div class="transaction-card-body"><div class="transaction-reference"><span><?=h(reference((int)$t['id']))?></span><span><?=$borrower?'Kamu meminjam':'Kamu pemilik'?></span></div><h2><a href="<?=h(url('transaction',['id'=>$t['id']]))?>"><?=h($t['item_name'])?></a></h2><p class="counterparty"><?=icon('user')?><?=$borrower?'Pemilik: ':'Peminjam: '?><?=h($borrower?$t['owner_name']:$t['borrower_name'])?></p><div class="period-row"><span>Periode pemakaian</span><strong><?=h(dateLabel($t['start_date']))?> – <?=h(dateLabel($t['end_date']))?></strong></div><?php if(late($t)):?><p class="late-note"><?=icon('alert')?>Melewati batas pengembalian</p><?php elseif($t['return_status']==='awaiting'):?><p class="waiting-note"><?=icon('clock')?><?=$borrower?'Menunggu pemilik memeriksa barang':'Peminjam sudah mengajukan pengembalian'?></p><?php else:?><p class="card-hint"><?=$t['status']==='completed'?'Barang sudah diterima kembali.':'Jaga barang seperti milikmu sendiri.'?></p><?php endif;?><a class="btn <?=$t['status']==='completed'?'btn-light':''?> btn-wide" href="<?=h(url(!$borrower&&$t['return_status']==='awaiting'?'confirmation':'transaction',['id'=>$t['id']]))?>"><?=$t['status']==='completed'?'Lihat riwayat':(!$borrower&&$t['return_status']==='awaiting'?'Periksa pengembalian':'Lihat transaksi')?><?=icon('arrow')?></a></div></article><?php endforeach;?></div><?php endif;?>
